(function(){"use strict";var CATEGORIES=[{key:"family",name:"Family",color:"#5fa3a0",subs:[{key:"relationships",name:"Relationships",statement:"I have strong, supportive relationships with my family members."},{key:"home",name:"Home",statement:"My home environment feels comfortable and supports my well-being."},{key:"time",name:"Quality Time",statement:"I spend enough quality time with the people who matter most to me."}]},{key:"emotional",name:"Emotional",color:"#d98a3d",subs:[{key:"awareness",name:"Awareness",statement:"I'm able to recognize and name what I'm feeling in the moment."},{key:"regulation",name:"Regulation",statement:"I can manage my emotions effectively, even under stress."},{key:"resilience",name:"Resilience",statement:"I bounce back from setbacks and difficult emotions reasonably well."}]},{key:"spiritual",name:"Spiritual",color:"#8e7cc3",subs:[{key:"purpose",name:"Purpose",statement:"I feel a sense of purpose or meaning in my life."},{key:"mindfulness",name:"Mindfulness",statement:"I regularly take time to be present and reflect."},{key:"values",name:"Values",statement:"My daily life aligns with my core values and beliefs."}]},{key:"physical",name:"Physical",color:"#5aa469",subs:[{key:"exercise",name:"Exercise",statement:"I get enough physical movement or exercise to feel good in my body."},{key:"sleep",name:"Sleep",statement:"I get enough quality sleep on a regular basis."},{key:"nutrition",name:"Nutrition",statement:"I eat in a way that supports my energy and health."}]},{key:"financial",name:"Financial",color:"#4f93b8",subs:[{key:"income",name:"Income",statement:"My income meets my current needs."},{key:"saving",name:"Saving",statement:"I feel confident about my savings and financial cushion."},{key:"spending",name:"Spending",statement:"I feel in control of my spending habits."}]},{key:"career",name:"Career",color:"#b5683f",subs:[{key:"purpose",name:"Purpose",statement:"My work feels meaningful and aligned with what matters to me."},{key:"growth",name:"Growth",statement:"I have opportunities to learn and grow in my career."},{key:"balance",name:"Balance",statement:"I maintain a healthy balance between work and the rest of my life."}]},{key:"educational",name:"Educational",color:"#7c5a9e",subs:[{key:"curiosity",name:"Curiosity",statement:"I make time to learn about things that interest me."},{key:"skills",name:"Skills",statement:"I'm developing skills that matter to my goals."},{key:"reflection",name:"Reflection",statement:"I take time to reflect on what I'm learning and how I'm growing."}]},{key:"social",name:"Social",color:"#d4707f",subs:[{key:"friends",name:"Friends",statement:"I have friendships that feel supportive and fulfilling."},{key:"community",name:"Community",statement:"I feel connected to a community or group I belong to."},{key:"connection",name:"Connection",statement:"I feel genuinely connected to the people around me."}]}];var STORAGE_KEY="exef-qol-wheel-v5";var SVGNS="http://www.w3.org/2000/svg";var CX=260,CY=260,R=150;var N_CATS=CATEGORIES.length;var SUBS_PER=3;var TOTAL_SUBS=N_CATS*SUBS_PER;var SUB_STEP=360/TOTAL_SUBS;var CAT_STEP=SUB_STEP*SUBS_PER;var START=-90-CAT_STEP/2;var IMP_WEIGHTS={low:1,medium:2,high:3};function clamp255(n){return Math.min(255,Math.max(0,n));}
function lighten(hex,amt){var r=clamp255(parseInt(hex.slice(1,3),16)+amt);var g=clamp255(parseInt(hex.slice(3,5),16)+amt);var b=clamp255(parseInt(hex.slice(5,7),16)+amt);return"#"+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);}
function luminance(hex){var ch=[parseInt(hex.slice(1,3),16),parseInt(hex.slice(3,5),16),parseInt(hex.slice(5,7),16)].map(function(v){v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);});return 0.2126*ch[0]+0.7152*ch[1]+0.0722*ch[2];}
function idealText(hex){return luminance(hex)>0.52?"#162b3c":"#ffffff";}
var SUBS=[];var subByKey={};CATEGORIES.forEach(function(cat,ci){cat.text="";cat.textColor=idealText(cat.color);var shades=[cat.color,lighten(cat.color,26),lighten(cat.color,50)];cat.subs.forEach(function(s,si){var rec={key:cat.key+"-"+s.key,catKey:cat.key,subName:s.name,statement:s.statement,color:shades[si],textColor:idealText(shades[si]),globalIndex:ci*SUBS_PER+si,value:5,importance:"medium"};SUBS.push(rec);subByKey[rec.key]=rec;});});var svg=document.getElementById("wheel");var catsEl=document.getElementById("cats");var $=function(id){return document.getElementById(id);};function polar(angleDeg,radius){var a=angleDeg*Math.PI/180;return{x:CX+radius*Math.cos(a),y:CY+radius*Math.sin(a)};}
function subWedgePath(globalIndex,value){var r=(value/10)*R;if(r<=0)return"";var a0=START+globalIndex*SUB_STEP;var a1=a0+SUB_STEP;var p0=polar(a0,r),p1=polar(a1,r);return"M "+CX+" "+CY+" L "+p0.x+" "+p0.y+" A "+r+" "+r+" 0 0 1 "+p1.x+" "+p1.y+" Z";}
function el(tag,attrs){var n=document.createElementNS(SVGNS,tag);for(var k in attrs)n.setAttribute(k,attrs[k]);return n;}
function buildWheel(){for(var g=1;g<=10;g++){svg.appendChild(el("circle",{cx:CX,cy:CY,r:(g/10)*R,class:"wheel-grid-ring"}));}
SUBS.forEach(function(s){svg.appendChild(el("path",{class:"wheel-wedge",fill:s.color,"fill-opacity":"0.82",id:"wedge-"+s.key}));});for(var c=0;c<N_CATS;c++){var p=polar(START+c*CAT_STEP,R);svg.appendChild(el("line",{x1:CX,y1:CY,x2:p.x,y2:p.y,class:"wheel-spoke"}));}
for(var si=0;si<TOTAL_SUBS;si++){if(si%SUBS_PER===0)continue;var ps=polar(START+si*SUB_STEP,R);svg.appendChild(el("line",{x1:CX,y1:CY,x2:ps.x,y2:ps.y,class:"wheel-spoke--minor"}));}
svg.appendChild(el("circle",{cx:CX,cy:CY,r:R,class:"wheel-outer"}));CATEGORIES.forEach(function(cat,i){var mid=START+i*CAT_STEP+CAT_STEP/2;var lp=polar(mid,R+24);var anchor=(lp.x<CX-4)?"end":(lp.x>CX+4)?"start":"middle";var t=el("text",{x:lp.x,y:lp.y+4,"text-anchor":anchor,class:"wheel-label"});t.textContent=cat.name;svg.appendChild(t);});svg.appendChild(el("circle",{cx:CX,cy:CY,r:R,class:"wheel-hit"}));var dragging=false;function applyFromEvent(evt){var pt=svg.createSVGPoint();var src=evt.touches?evt.touches[0]:evt;pt.x=src.clientX;pt.y=src.clientY;var loc=pt.matrixTransform(svg.getScreenCTM().inverse());var dx=loc.x-CX,dy=loc.y-CY;var dist=Math.sqrt(dx*dx+dy*dy);var ang=Math.atan2(dy,dx)*180/Math.PI;var rel=((ang-START)%360+360)%360;var gi=Math.floor(rel/SUB_STEP);if(gi<0||gi>=TOTAL_SUBS)return;var val=Math.max(0,Math.min(10,Math.round((dist/R)*10)));setSubValue(SUBS[gi].key,val);}
svg.addEventListener("mousedown",function(e){dragging=true;applyFromEvent(e);e.preventDefault();});window.addEventListener("mousemove",function(e){if(dragging)applyFromEvent(e);});window.addEventListener("mouseup",function(){dragging=false;});svg.addEventListener("touchstart",function(e){dragging=true;applyFromEvent(e);e.preventDefault();},{passive:false});svg.addEventListener("touchmove",function(e){if(dragging){applyFromEvent(e);e.preventDefault();}},{passive:false});svg.addEventListener("touchend",function(){dragging=false;});}
function buildCards(){CATEGORIES.forEach(function(cat){var card=document.createElement("div");card.className="cat";card.style.setProperty("--cat-color",cat.color);card.style.setProperty("--cat-text",cat.textColor);var html='<div class="cat__head">'+'<span class="cat__dot"></span>'+'<span class="cat__name">'+cat.name+'</span>'+'<span class="cat__avg" id="catavg-'+cat.key+'" title="Weighted average for '+cat.name+'">0.0</span>'+'</div>'+'<label class="cat__define-label" for="text-'+cat.key+'">Define: '+cat.name+'</label>'+'<textarea id="text-'+cat.key+'" placeholder="What does '+cat.name.toLowerCase()+' mean to you?"></textarea>'+'<div class="subs">';cat.subs.forEach(function(sub){var rec=subByKey[cat.key+"-"+sub.key];html+='<div class="sub-row" style="--track-color:'+rec.color+';--track-text:'+rec.textColor+'">'+'<span class="sub-name">'+sub.statement+'</span>'+'<span class="sub-val" id="val-'+rec.key+'">5</span>'+'<div class="sub-slider-row">'+'<span class="ends">Disagree</span>'+'<input type="range" id="range-'+rec.key+'" min="1" max="10" step="1" value="5" '+'aria-label="'+cat.name+' &ndash; '+sub.name+': '+sub.statement+' From 1 (strongly disagree) to 10 (strongly agree)">'+'<span class="ends">Agree</span>'+'</div>'+'<div class="imp-row" role="group" aria-label="'+sub.name+' importance">'+'<span class="imp-label">Importance</span>'+'<button type="button" class="imp-btn" data-key="'+rec.key+'" data-imp="low" aria-pressed="false">Low</button>'+'<button type="button" class="imp-btn" data-key="'+rec.key+'" data-imp="medium" aria-pressed="true">Med</button>'+'<button type="button" class="imp-btn" data-key="'+rec.key+'" data-imp="high" aria-pressed="false">High</button>'+'</div>'+'</div>';});html+='</div>';card.innerHTML=html;catsEl.appendChild(card);cat.subs.forEach(function(sub){var key=cat.key+"-"+sub.key;$("range-"+key).addEventListener("input",function(e){setSubValue(key,parseInt(e.target.value,10));});});card.querySelectorAll(".imp-btn").forEach(function(btn){btn.addEventListener("click",function(){setImportance(btn.getAttribute("data-key"),btn.getAttribute("data-imp"));});});$("text-"+cat.key).addEventListener("input",function(e){getCat(cat.key).text=e.target.value;save();});});}
function getCat(key){for(var i=0;i<CATEGORIES.length;i++)if(CATEGORIES[i].key===key)return CATEGORIES[i];return null;}
function setSubValue(key,val){var rec=subByKey[key];if(!rec)return;rec.value=val;$("wedge-"+key).setAttribute("d",subWedgePath(rec.globalIndex,val));$("val-"+key).textContent=val;var range=$("range-"+key);range.value=val;range.style.setProperty("--fill",(val*10)+"%");updateCatAverage(rec.catKey);updateGlobalAverage();save();}
function setImportance(key,level){var rec=subByKey[key];if(!rec)return;rec.importance=level;var row=$("range-"+key).closest(".sub-row");row.querySelectorAll(".imp-btn").forEach(function(btn){btn.setAttribute("aria-pressed",btn.getAttribute("data-imp")===level?"true":"false");});updateCatAverage(rec.catKey);updateGlobalAverage();save();}
function weightedAvg(records){var sumW=0,sumVW=0;records.forEach(function(rec){var w=IMP_WEIGHTS[rec.importance]||2;sumW+=w;sumVW+=rec.value*w;});return sumW>0?sumVW/sumW:0;}
function updateCatAverage(catKey){var recs=SUBS.filter(function(s){return s.catKey===catKey;});$("catavg-"+catKey).textContent=weightedAvg(recs).toFixed(1);}
function updateGlobalAverage(){$("avg").textContent=weightedAvg(SUBS).toFixed(1);}
var saveTimer=null;function save(){var data={name:$("name").value,date:$("date").value,cats:{},subs:{}};CATEGORIES.forEach(function(c){data.cats[c.key]={text:c.text};});SUBS.forEach(function(s){data.subs[s.key]={value:s.value,importance:s.importance};});try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));}catch(e){}
var note=$("saveNote");note.textContent="Saved on this device";clearTimeout(saveTimer);saveTimer=setTimeout(function(){note.textContent="";},1500);}
function load(){var raw;try{raw=localStorage.getItem(STORAGE_KEY);}catch(e){raw=null;}
if(!raw)return;var data;try{data=JSON.parse(raw);}catch(e){return;}
$("name").value=data.name||"";$("date").value=data.date||"";CATEGORIES.forEach(function(cat){if(data.cats&&data.cats[cat.key]){cat.text=data.cats[cat.key].text||"";$("text-"+cat.key).value=cat.text;}});SUBS.forEach(function(s){var item=data.subs&&data.subs[s.key];if(item){setImportance(s.key,item.importance||"medium");setSubValue(s.key,typeof item.value==="number"?item.value:5);}});}
function download(){var lines=["THE QUALITY OF LIFE WHEEL"];lines.push("Name: "+($("name").value||"(blank)"));lines.push("Date: "+($("date").value||"(blank)"));lines.push("");CATEGORIES.forEach(function(cat){var recs=SUBS.filter(function(s){return s.catKey===cat.key;});lines.push("=== "+cat.name.toUpperCase()+"  (avg "+weightedAvg(recs).toFixed(1)+"/10) ===");if(cat.text)lines.push("  Definition: "+cat.text);recs.forEach(function(rec){lines.push("  "+rec.subName+" - \""+rec.statement+"\": "+rec.value+"/10  [importance: "+rec.importance+"]");});lines.push("");});lines.push("Overall weighted average: "+weightedAvg(SUBS).toFixed(1)+"/10");var blob=new Blob([lines.join("\n")],{type:"text/plain"});var url=URL.createObjectURL(blob);var a=document.createElement("a");a.href=url;a.download="quality-of-life-wheel.txt";document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function resetAll(){if(!confirm("Reset every rating, importance, and definition back to the middle?"))return;CATEGORIES.forEach(function(cat){cat.text="";$("text-"+cat.key).value="";});SUBS.forEach(function(s){setImportance(s.key,"medium");setSubValue(s.key,5);});}
buildWheel();buildCards();$("name").addEventListener("input",save);$("date").addEventListener("input",save);$("print").addEventListener("click",function(){window.print();});$("download").addEventListener("click",download);$("reset").addEventListener("click",resetAll);load();if(!$("date").value){$("date").value=new Date().toISOString().slice(0,10);}
SUBS.forEach(function(s){setImportance(s.key,s.importance);setSubValue(s.key,s.value);});})();